    27→const getPaginationItems = (currentPage: number, totalPages: number) => {
    28→  const items: Array<{ type: 'page' | 'ellipsis'; value: number }> = [];
    29→
    30→  if (totalPages <= 7) {
    31→    // Show all pages if total is 7 or less
    32→    for (let i = 1; i <= totalPages; i++) {
    33→      items.push({ type: 'page', value: i });
    34→    }
    35→  } else {
    36→    // Always show first page
    37→    items.push({ type: 'page', value: 1 });
    38→
    39→    if (currentPage <= 4) {
    40→      // Show pages 2-5, then ellipsis, then last page
    41→      for (let i = 2; i <= 5; i++) {
    42→        items.push({ type: 'page', value: i });
    43→      }
    44→      items.push({ type: 'ellipsis', value: 0 });
    45→      items.push({ type: 'page', value: totalPages });
    46→    } else if (currentPage >= totalPages - 3) {
    47→      // Show first page, ellipsis, then pages totalPages-4 to totalPages
    48→      items.push({ type: 'ellipsis', value: 0 });
    49→      for (let i = totalPages - 4; i <= totalPages; i++) {
    50→        items.push({ type: 'page', value: i });
    51→      }
    52→    } else {
    53→      // Show first page, ellipsis, current page and neighbors, ellipsis, last page
    54→      items.push({ type: 'ellipsis', value: 0 });
    55→      for (let i = currentPage - 1; i <= currentPage + 1; i++) {
    56→        items.push({ type: 'page', value: i });
    57→      }
    58→      items.push({ type: 'ellipsis', value: 0 });
    59→      items.push({ type: 'page', value: totalPages });
    60→    }
    61→  }
    62→
    63→  return items;
    64→};
